// Создаёт коллекцию Qdrant sku_catalog, если её нет.
let status = 'exists';
try {
  await this.helpers.httpRequest({ method: 'GET', url: 'http://qdrant:6333/collections/sku_catalog', json: true });
} catch (e) {
  try {
    await this.helpers.httpRequest({
      method: 'PUT',
      url: 'http://qdrant:6333/collections/sku_catalog',
      body: { vectors: { size: 1024, distance: 'Cosine' } },
      json: true
    });
    status = 'created';
  } catch (e2) {
    throw new Error('Qdrant недоступен, коллекцию создать не удалось: ' + (e2.cause && e2.cause.message ? e2.cause.message : e2.message));
  }
}
return { json: { collection: 'sku_catalog', status: status } };

// Собираем тексты для bge-m3. Пустой справочник = сбой ERP:
// прерываем тик, коллекцию НЕ трогаем (защита от wipe).
const rows = $input.all().map(x => x.json).filter(r => r && r.code && r.item_name);
if (!rows.length) {
  throw new Error('ERP_EMPTY: справочник пуст или недоступен — рефреш отменён');
}
return [{ json: {
  items: rows.map(r => ({ code: String(r.code), item_name: String(r.item_name).slice(0, 1000) })),
  texts: rows.map(r => String(r.item_name).slice(0, 1000))
} }];

// Точки Qdrant: id — детерминированный UUID v5 от кода SKU
// (код текстовый, Qdrant требует число/UUID; crypto разрешён через
// NODE_FUNCTION_ALLOW_BUILTIN).
const crypto = require('crypto');
function uuid5(text) {
  const h = crypto.createHash('sha1').update('sku:' + text).digest();
  h[6] = (h[6] & 0x0f) | 0x50;
  h[8] = (h[8] & 0x3f) | 0x80;
  const hex = h.toString('hex');
  return hex.slice(0, 8) + '-' + hex.slice(8, 12) + '-' + hex.slice(12, 16) + '-' + hex.slice(16, 20) + '-' + hex.slice(20, 32);
}
const src = $('Prepare texts').first().json;
const embs = $json.embeddings || [];
if (!Array.isArray(embs) || embs.length !== src.items.length) {
  throw new Error('EMBED_MISMATCH: ожидалось ' + src.items.length + ' векторов, пришло ' + embs.length);
}
const points = src.items.map((it, i) => ({
  id: uuid5(it.code),
  vector: embs[i],
  payload: { code: it.code, item_name: it.item_name }
}));
return { json: {
  points: points,
  codes: src.items.map(it => it.code)
} };

// Удаляем из sku_catalog точки, чьих кодов больше нет в ERP
// (полный рефреш: коллекция = зеркало справочника).
const current = new Set($('Build points').first().json.codes.map(String));
let stale = [];
let offset = null;
do {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://qdrant:6333/collections/sku_catalog/points/scroll',
    body: { limit: 256, with_payload: true, with_vector: false, offset: offset },
    json: true
  });
  const pts = (resp.result && resp.result.points) || [];
  for (const p of pts) {
    const c = p.payload && p.payload.code;
    if (!current.has(String(c))) stale.push(p.id);
  }
  offset = resp.result && resp.result.next_page_offset;
} while (offset);
if (stale.length) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://qdrant:6333/collections/sku_catalog/points/delete?wait=true',
    body: { points: stale },
    json: true
  });
}
return { json: { sku_total: current.size, stale_deleted: stale.length } };
